INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (306906, 13731, 'France 24', 'en', 'Israeli troops fail to remove settlers besieging Palestinian homes in West Bank village', 'https://www.france24.com/en/middle-east/20260812-israeli-settlers-keep-up-siege-of-palestinian-homes-despite-rare-military-intervention', 'The Israeli military on Wednesday failed to remove settlers from blockaded Palestinian homes in the occupied West Bank. The siege began over the weekend, when a group of settlers blocked essential supplies from entering the Palestinian village of Qusra. The incident marked a ⁠rare confrontation between settlers and the Israeli military.', 'https://s.france24.com/media/display/96c3ce4c-965b-11f1-8136-005056a97e36/w:1024/p:16x9/6ffb5b0479fa6fc1ed95326ff10361ceb759b847.jpg', '2026-08-12T14:39:14+00:00', '2026-08-12T22:51:09.346577'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
