INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (321045, 13731, 'Deutsche Welle', 'en', 'Israeli military moves as settlers besiege 3 West Bank homes', 'https://www.dw.com/en/israeli-military-moves-as-settlers-besiege-3-west-bank-homes/a-78355266?maca=en-rss-en-world-4025-xml-mrss', 'Israel''s military has moved to try to stop a group of settlers from besieging three homes in the occupied West Bank. One was owned by a Palestinian American, prompting an unusually sharp rebuke from the US ambassador.', '', '2026-08-13T15:19:00+00:00', '2026-08-13T22:50:51.855608'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (321097, 13731, 'France 24', 'en', 'West Bank: "In recent weeks, we''ve seen a striking escalation in violent acts"', 'https://www.france24.com/en/video/20260813-west-bank-in-recent-weeks-we-ve-seen-a-striking-escalation-in-violent-acts', 'Israeli forces on Thursday moved against rogue settlers laying siege to Palestinians amid unusually strong US criticism, even as Israel inaugurated an emblematic settlement elsewhere in the West Bank. Our correspondent Noga Tarnopolsky tells us more.', 'https://s.france24.com/media/display/0f6853a0-9723-11f1-8554-005056a97e36/w:1024/p:16x9/EN-20260813-150051-150556-CS.jpg', '2026-08-13T15:11:07+00:00', '2026-08-13T22:50:55.879552'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (321101, 13731, 'France 24', 'en', 'West Bank: "What we see is an escalation in methods"', 'https://www.france24.com/en/video/20260813-west-bank-what-we-see-is-an-escalation-in-methods', 'Israeli settlers have besieged three homes in the occupied West Bank for several days, including one owned by a Palestinian American, in what the US ambassador called a "horrific act of terror" on Thursday. We discuss the situation with our guest, Allegra Pacheco, chief of party of the West Bank Protection Consortium.', 'https://s.france24.com/media/display/32df1b8a-9722-11f1-872b-005056a90284/w:1024/p:16x9/EN-20260813-130334-131144-CS.jpg', '2026-08-13T14:58:33+00:00', '2026-08-13T22:50:55.915527'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
