INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (325369, 13731, 'NBC News', 'en', 'U.S. Ambassador Huckabee condemns ‘Israeli terrorists’ for siege of West Bank homes', 'https://www.nbcnews.com/video/u-s-ambassador-condemns-israeli-terrorists-for-siege-of-west-bank-homes-268286021795', 'Dozens of Israeli settlers have trapped two Palestinian families in their West Bank homes for days, cutting off food, water and electricity. Their actions even drawing the ire of U.S. Ambassador to Israel Mike Huckabee. The IDF says settlers were dispersed, but some remain. NBC News'' Matt Bradley reports from the occupied West Bank.', 'https://prodamdnewsencoding.akamaized.net/NBC_News_Digital/now_hallie_mbr_west_bank_flareup_260813/1/abs/index.m3u8', '2026-08-13T23:28:41+00:00', '2026-08-14T00:04:54.664067'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
