INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (306744, 13746, 'The Guardian', 'en', 'Trump sued over $100,000-a-month early-access offer to Truth Social posts', 'https://www.theguardian.com/us-news/2026/aug/12/truth-social-suit-trump-early-access-offer', 'Suit alleges subscription offer aims to sell privileged access to information generated in president’s official capacity Donald Trump has been sued after a subscription service charging up to $100,000 a month for early access to his posts on his Truth Social platform sparked allegations of corruption. The lawsuit, filed in the US district court for the southern district of New York , was brought by the Intercept and the Freedom of the Press Foundation against Trump, two of his aides and the executive office of the president. Continue reading...', 'https://i.guim.co.uk/img/media/1c8c1afe31bd6860a58bffb184bc04e661980f67/648_0_6882_5504/master/6882.jpg?width=140&quality=85&auto=format&fit=max&s=0d09a4ce2424eede87f595250e4f6a74', '2026-08-12T17:30:21+00:00', '2026-08-12T22:50:52.807143'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
