INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (320925, 13746, 'The Guardian', 'en', 'Trump-led board reportedly votes again to close Kennedy Center for renovations', 'https://www.theguardian.com/us-news/live/2026/aug/13/karoline-leavitt-white-house-primaries-trump-politics-latest-updates', 'In May, a judge issued a temporary block on Trump’s demand to close the arts institution for renovations after the board – mostly handpicked by the president – voted unanimously in favor Sign up for the Breaking News US email Donald Trump’s executive order on vaccines does not change the US recommendations for the shots – but experts say it does create confusion and doubt about vaccines, which will lead to more illness and possibly deaths among children and will make it harder for families and pediatricians to protect them. The executive order was an attempt to reinstate sweeping changes to th', 'https://i.guim.co.uk/img/media/e6d485d3ed1fb966c243e092dc81b8313ecfad69/919_0_6830_5464/master/6830.jpg?width=140&quality=85&auto=format&fit=max&s=470339298cc8e2654051a12db029df7f', '2026-08-13T22:25:08+00:00', '2026-08-13T22:50:38.057672'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (320936, 13746, 'The Guardian', 'en', 'Trump has amassed staggering wealth in ‘most openly corrupt’ presidency', 'https://www.theguardian.com/us-news/2026/aug/13/trump-presidency-revenue-wealth', 'Ethics experts and Democrats express alarm as Trump uses office to grow his personal fortune to ‘unprecedented’ level Donald Trump ’s use of his second presidency to grow his personal fortune has alarmed legal and ethics experts and congressional Democrats as he has reaped an “unprecedented” $2.2bn in 2025 revenues by amassing big cryptocurrency holdings, benefiting from wealthy foreign interests, expanding his Truth Social business and more, while federal oversight of his actions has waned. Trump last year raked in at least $1.4bn from his crypto ventures according to financial disclosure for', 'https://i.guim.co.uk/img/media/501f7dc88b2aca174fb4d359c71fa885db8af59e/601_0_3001_2401/master/3001.jpg?width=140&quality=85&auto=format&fit=max&s=39778106710b96622bc7a52e0669c439', '2026-08-13T12:00:03+00:00', '2026-08-13T22:50:40.025229'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
