INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (321042, 13746, 'Deutsche Welle', 'en', 'Kennedy Center board approves Trump name on facade, renovation plan', 'https://www.dw.com/en/kennedy-center-board-approves-trump-name-on-facade-renovation-plan/a-78359935?maca=en-rss-en-world-4025-xml-mrss', 'The move appears designed to circumvent a judge''s ruling that the US president''s name should be removed, potentially setting the stage for a new legal fight over the Kennedy Center''s name and future.', '', '2026-08-13T20:33:00+00:00', '2026-08-13T22:50:51.825854'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
